def base(i,source=True):
    return {"id":i,"version":"0.1.0","status":"CANDIDATE","source_refs":[SRC] if source else [],"evidence_refs":[],"extensions":{}}
def step(i,role,action,why,out):
    return {"id":i,"role":role,"action":action,"why_valid":why,"inputs":[],"output":out}
def model(summary,reasoning,check):
    return {"kind":"MODEL_RESPONSE","summary":summary,"reasoning":reasoning,"check":check,"acceptable_alternatives":[],"subpart_answers":[],"verification_status":"CHECKED_BY_AUTHOR"}
def misconception(wrong,diagnostic,repair):
    return {"wrong_idea":wrong,"diagnostic_prompt":diagnostic,"repair":repair}
def representation(i,purpose,asset,stages,relations,correspondence):
    return {**base(i,False),"kind":"GEOMETRIC_CONSTRUCTION","purpose":purpose,"required_elements":[s[1] for s in stages],
      "relation_refs":relations,"read_order":[s[2] for s in stages],
      "instance_constraints":["The visual uses a changed teaching case and must not reveal the supplied source-question outcome."],
      "accessibility":["Accessible SVG title/description are required; text duplicates structural meaning."],
      "misleading_alternatives":["Treating the changed case as an answer key for the protected source question."],
      "rendered_asset_refs":[asset],"scene_instances":[],"correspondence":correspondence,
      "reveal_stages":[{"id":sid,"label":label,"purpose":job,"visible_elements":[label]} for sid,label,job in stages]}

