for qid,row in zip(STEMS,bank["questions"]):
    review=QR[qid]; row["id"]=IDS[qid]; row["original_identifier"]=qid
    row["primary_capability_ref"]=PRIMARY[qid]; row["family_ref"]=FAMILY[qid]
    row["conditions"]=CONDITIONS[qid]; row["figure_refs"]=[]
    moves=[]
    for n,(kind,action,why,out) in enumerate(MOVE[qid],1):
        moves.append({"id":f"{IDS[qid]}-MOVE-{n}","kind":kind,"action":action,"why_valid":why,"inputs":["stated givens and prior moves"],"output":out})
    # The first move of Q8 is the decisive representation; for the other items use the second move when available.
    crux=0 if qid=="Q8" else min(1,len(moves)-1)
    row["answer"]={"kind":"EXACT","summary":review["verified_answer"],"reasoning_route":moves,"crux_move_ref":moves[crux]["id"],"check":review["independent_check"],"verification_status":"CHECKED_BY_AUTHOR"}
    hints=list(review["hints"])+EXTRA_HINTS.get(qid,[])
    stages=["KEY_CONCEPT","REPRESENTATION","CRUX","FORMAL_MODEL","CHECKPOINT"]
    kinds=["CONNECT","REPRESENT","CONNECT","EXECUTE","EXECUTE"]
    row["scaffolds"]=[{"text":h,"support_kind":kinds[i],"reveals":"CONCEPT" if i<2 else "METHOD","learner_stage":stages[i],"supports_move_ref":moves[min(i,len(moves)-1)]["id"]} for i,h in enumerate(hints)]
    a=row["extensions"].setdefault("grade9v3:analysis",{})
    a["learner_question_type"]="constructed_response"; a["difficulty"]={**review["difficulty"],"basis":f"{review['X']} Decisive bridge: {review['Z']} Score {review['difficulty']['score']} resolves to {review['difficulty']['band']}."}
    a["common_wrong_route"]=review["misconception"]["M1"]; a["expected_time_seconds"]={"D1":75,"D2":150,"D3":240,"D4":330}[review["difficulty"]["band"]]
    a["cognitive_demand"]=review["demand"]; a["stable_crux_move"]=review["Z"]
    row["extensions"]["grade9v3:authorship"]={"kind":"COORDINATOR_AI_DRAFTED","owner_authorized":True,"claim":"Benchmark input, not official/PYQ and not personally authored by Owner."}
    row["extensions"]["grade9v3:math_spans"]=[]
    row["extensions"]["grade9v3:component_waivers"]={"REPRESENTATION":review["representation"]["reason"]}
    repair=dict(review["repair"]); repair.update({"question_ref":IDS[qid],"construction_ref":CONSTRUCTION[qid],"crux_move_ref":moves[crux]["id"],"label":qid})
    row["extensions"]["grade9v3:learning_repair"]=repair
    row.pop("hints",None); row.pop("hint_ladder",None)

by_id={q["id"]:q for q in bank["questions"]}
def repair(qid):
    return dict(by_id[IDS[qid]]["extensions"]["grade9v3:learning_repair"])
def anchor(unit,qid,stem,summary,reasoning,check):
    q=by_id[IDS[qid]]
    return {"id":f"ANCHOR-{unit}","target_question_ref":q["id"],"target_crux_move_ref":q["answer"]["crux_move_ref"],"construction_ref":unit,
            "stem":stem,"answer":{"summary":summary,"reasoning":reasoning,"check":check}}

