factor_steps=[step("MF1","DECLARE","Separate zero location, multiplicity and any extra value/parameter condition.","Different facts constrain different parts of the polynomial.","condition map"),step("MF2","TRANSFORM","Keep repeated factors visible while completing the factor structure.","The exponent records multiplicity at one location.","factor structure"),step("MF3","TRANSFORM","For sign work, partition by distinct zeros and multiply factor signs.","A product's sign follows from its factors on each interval.","interval signs"),step("MF4","VERIFY","Use expansion or exact nearby values as a second route.","The check is independent of an assumed graph shape.","verified structure")]
id_steps=[step("MI1","DECLARE","State only what the supplied zeros or agreements force.","This prevents a degree assumption from being smuggled in.","minimal consequence"),step("MI2","TRANSFORM","For identity claims, define the difference polynomial.","Agreement becomes zeros of one polynomial.","difference polynomial"),step("MI3","TRANSFORM","Assume the difference is nonzero before applying the distinct-root bound.","The theorem excludes the zero polynomial.","contradiction branch"),step("MI4","VERIFY","Interpret the remaining zero-polynomial case or give a counterexample when no degree bound exists.","This closes the logic without overclaiming.","global conclusion or counterexample")]
model_steps=[step("MM1","DECLARE","Write whole and removed quantities separately.","The context fixes the algebraic components.","component model"),step("MM2","TRANSFORM","Combine and simplify the complete expressions.","Leading terms may cancel.","simplified polynomial"),step("MM3","VERIFY","Check one admissible input in both forms.","Matching values test the translation.","model check")]
domain_steps=[step("MD1","DECLARE","Name the condition being tested and any substitution image.","Root, degree and zero-polynomial conditions are different; y=x^2 has y>=0.","condition map"),step("MD2","TRANSFORM","Solve the reduced algebraic condition.","This exposes candidate parameter or auxiliary values.","candidate values"),step("MD3","TRANSFORM","Filter by coefficient/domain restrictions.","Only admissible candidates survive.","filtered values"),step("MD4","VERIFY","Return to the original polynomial and check.","The original formulation is authoritative.","verified conclusion")]

microtopics=[
micro(MIC_FACTOR,"Factors, multiplicity and sign",CAP_FACTOR,"HARD","Factor form carries zero location, multiplicity and interval-sign information that must not be collapsed into one claim.",factor_steps,[REL_FACTOR,REL_SIGN],REP_FACTOR,FAM_FACTOR,misconception("A repeated factor creates another distinct zero or every zero changes sign.","List zero locations and exponents in separate columns before deciding signs.","Treat location, multiplicity and sign behaviour as separate pieces of evidence."),"For F(x)=(x+1)^2(x-3), list the distinct zeros and say where the sign changes.","Distinct zeros are -1 and 3; sign is preserved at -1 and changes at 3.",["The square gives even multiplicity at -1.","The factor x-3 has odd multiplicity."],"Use exact values on both sides.","CU-ISS51-FACTOR-SIGN",["Q2","Q6"],"MF4",[{"statement":"CHECK: Does a squared factor create a second zero location?","role":"CHECK"},{"statement":"APPLY: Predict sign change for (x-4)^3.","role":"APPLY"},{"statement":"CONNECT: Explain why exact nearby values can check a factor-sign conclusion.","role":"CONNECT"}],anchor("CU-ISS51-FACTOR-SIGN","Q2","For F(x)=(x+1)^2(x-3), distinguish distinct zeros from multiplicity and predict sign change at each zero.","Distinct zeros are -1 and 3; no sign change at -1, sign change at 3.",["Read locations from factors.","Read multiplicity from exponents.","Use factor signs across each zero."],"Exact nearby values confirm the predictions."),["Q1","Q2","Q5","Q6"]),
micro(MIC_ID,"Degree bounds and polynomial identity",CAP_ID,"HARD","A degree bound becomes useful only after the right auxiliary object is built; for identity, agreement must become zeros of a difference polynomial and the zero-polynomial branch must remain explicit.",id_steps,[REL_ID,REL_FACTOR],REP_ID,FAM_ID,misconception("Every polynomial of degree at most n has at most n zeros, including the zero polynomial.","State the nonzero hypothesis before invoking the root-count theorem.","Use contradiction only for a nonzero difference; then interpret the identically-zero case."),"Two real polynomials of degree at most one agree at two distinct inputs. Must they agree everywhere?","Yes. Let h=f-g; two h-zeros contradict a nonzero degree-at-most-one h, so h is identically zero.",["Convert agreement to h-zeros.","Invoke the root bound only under h nonzero.","Interpret h identically zero."],"A nonzero linear polynomial cannot have two distinct roots.","CU-ISS51-DEGREE-IDENTITY",["Q7","Q8"],"MI4",[{"statement":"CHECK: State the root-count fact with the word nonzero.","role":"CHECK"},{"statement":"APPLY: For degree at most three, how many agreement inputs force identity by this method?","role":"APPLY"},{"statement":"CONNECT: Explain why known zeros alone imply divisibility but not a degree cap.","role":"CONNECT"}],anchor("CU-ISS51-DEGREE-IDENTITY","Q8","Suppose f and g are real polynomials of degree at most one and agree at two distinct real inputs. Must they agree everywhere?","Yes. Let h=f-g; if h were nonzero it would have too many distinct zeros, so h is the zero polynomial.",["Define h=f-g.","Translate the two agreements into h-zeros.","Assume h nonzero and derive the degree-one contradiction.","Interpret h identically zero."],"A nonzero degree-at-most-one polynomial has at most one distinct root."),["Q3","Q7","Q8"]),
micro(MIC_MODEL,"Model first, then simplify",CAP_MODEL,"MEDIUM","The degree of a combined polynomial belongs to the simplified result; component leading terms may cancel after a faithful contextual model is built.",model_steps,[REL_MODEL],REP_MODEL,FAM_MODEL,misconception("Two quadratic component areas must combine to a quadratic result.","Compare the leading terms after writing whole minus removed.","Determine degree only after exact simplification."),"An outer rectangle is (x+5) by (x+1) and an x by x square is removed. What degree remains?","The remaining area is 6x+5, which is linear.",["Write whole minus removed.","Expand: x^2+6x+5-x^2.","The leading terms cancel."],"At x=1, 12-1=11=6(1)+5.","CU-ISS51-MODEL-CANCEL",["Q4"],"MM2",[{"statement":"CHECK: Which expression is the whole and which is removed?","role":"CHECK"},{"statement":"APPLY: Simplify a changed frame model.","role":"APPLY"},{"statement":"CONNECT: Explain how cancellation can lower degree.","role":"CONNECT"}],anchor("CU-ISS51-MODEL-CANCEL","Q4","An outer rectangle is (x+5) by (x+1) and an x by x square is removed. Find the remaining-area polynomial and its degree.","6x+5, degree 1.",["Model (x+5)(x+1)-x^2.","Expand and cancel x^2."],"At x=1 both forms give 11."),["Q4"]),
micro(MIC_DOMAIN,"Parameters and auxiliary-variable domains",CAP_DOMAIN,"HARD","A parameter condition constrains specific coefficients or values, while an auxiliary substitution is a mapping whose image must travel through the algebra.",domain_steps,[REL_DOMAIN,REL_FACTOR],REP_DOMAIN,FAM_MODEL,misconception("After setting y=x^2, y can be any real number; or a vanished leading coefficient makes the whole polynomial zero.","Ask what y=x^2 can actually equal and which coefficients remain after a degree drop.","Carry the substitution image and test all coefficients for a zero-polynomial claim."),"Solve x^4+3x^2-4=0 over the reals by y=x^2.","Use y>=0; y^2+3y-4=0 gives y=1 or -4, retain y=1, so x=+/-1.",["Declare y>=0.","Solve in y.","Filter, then return to x."],"Substitute x=+/-1 into the original quartic.","CU-ISS51-PARAM-DOMAIN",["Q9","Q10"],"MD4",[{"statement":"CHECK: What image condition follows from y=x^2 over real x?","role":"CHECK"},{"statement":"APPLY: Filter the y-roots of a changed even-power quartic.","role":"APPLY"},{"statement":"CONNECT: Explain why degree<3 is weaker than being the zero polynomial.","role":"CONNECT"}],anchor("CU-ISS51-PARAM-DOMAIN","Q10","Solve x^4+3x^2-4=0 over the reals using y=x^2, preserving the auxiliary-variable condition.","The real zeros are +/-1.",["Set y=x^2 with y>=0.","Solve (y+4)(y-1)=0.","Reject y=-4 and map y=1 to x=+/-1."],"Direct substitution gives zero."),["Q9","Q10"])
]

